-- Create "rate_windows" table
CREATE TABLE `rate_windows` (`id` varchar(32) NOT NULL, `created_at` datetime(6) NOT NULL, `key` varchar(255) NOT NULL, `window_start` datetime(6) NOT NULL, `count` bigint NOT NULL DEFAULT 0, PRIMARY KEY (`id`), UNIQUE INDEX `key` (`key`)) CHARSET utf8mb4 COLLATE utf8mb4_bin;
-- Create "users" table
CREATE TABLE `users` (`id` varchar(32) NOT NULL, `created_at` datetime(6) NOT NULL, `updated_at` datetime(6) NOT NULL, `email` varchar(255) NULL, `name` varchar(80) NULL, `image` varchar(2048) NULL, `locale` varchar(16) NULL, PRIMARY KEY (`id`), UNIQUE INDEX `email` (`email`)) CHARSET utf8mb4 COLLATE utf8mb4_bin;
-- Create "verification_codes" table
CREATE TABLE `verification_codes` (`id` varchar(32) NOT NULL, `created_at` datetime(6) NOT NULL, `email` varchar(255) NOT NULL, `code_hash` varchar(64) NOT NULL, `attempts` bigint NOT NULL DEFAULT 0, `expires_at` datetime(6) NOT NULL, PRIMARY KEY (`id`), INDEX `verificationcode_email_created_at` (`email`, `created_at`)) CHARSET utf8mb4 COLLATE utf8mb4_bin;
-- Create "identities" table
CREATE TABLE `identities` (`id` varchar(32) NOT NULL, `created_at` datetime(6) NOT NULL, `provider` varchar(32) NOT NULL, `subject` varchar(255) NOT NULL, `user_id` varchar(32) NOT NULL, PRIMARY KEY (`id`), UNIQUE INDEX `identity_provider_subject` (`provider`, `subject`), INDEX `identity_user_id` (`user_id`), CONSTRAINT `identities_users_identities` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`) ON UPDATE NO ACTION ON DELETE CASCADE) CHARSET utf8mb4 COLLATE utf8mb4_bin;
-- Create "teams" table
CREATE TABLE `teams` (`id` varchar(32) NOT NULL, `created_at` datetime(6) NOT NULL, `name` varchar(100) NOT NULL, PRIMARY KEY (`id`)) CHARSET utf8mb4 COLLATE utf8mb4_bin;
-- Create "invites" table
CREATE TABLE `invites` (`id` varchar(32) NOT NULL, `created_at` datetime(6) NOT NULL, `token_hash` varchar(64) NOT NULL, `expires_at` datetime(6) NOT NULL, `used_at` datetime(6) NULL, `team_id` varchar(32) NOT NULL, PRIMARY KEY (`id`), INDEX `invite_team_id` (`team_id`), UNIQUE INDEX `token_hash` (`token_hash`), CONSTRAINT `invites_teams_invites` FOREIGN KEY (`team_id`) REFERENCES `teams` (`id`) ON UPDATE NO ACTION ON DELETE CASCADE) CHARSET utf8mb4 COLLATE utf8mb4_bin;
-- Create "memberships" table
CREATE TABLE `memberships` (`id` varchar(32) NOT NULL, `created_at` datetime(6) NOT NULL, `role` enum('admin','member') NOT NULL, `team_id` varchar(32) NOT NULL, `user_id` varchar(32) NOT NULL, PRIMARY KEY (`id`), INDEX `membership_team_id` (`team_id`), UNIQUE INDEX `membership_user_id_team_id` (`user_id`, `team_id`), CONSTRAINT `memberships_teams_memberships` FOREIGN KEY (`team_id`) REFERENCES `teams` (`id`) ON UPDATE NO ACTION ON DELETE CASCADE, CONSTRAINT `memberships_users_memberships` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`) ON UPDATE NO ACTION ON DELETE CASCADE) CHARSET utf8mb4 COLLATE utf8mb4_bin;
-- Create "passwords" table
CREATE TABLE `passwords` (`id` varchar(32) NOT NULL, `created_at` datetime(6) NOT NULL, `updated_at` datetime(6) NOT NULL, `hash` varchar(512) NOT NULL, `must_change` bool NOT NULL DEFAULT 0, `user_id` varchar(32) NOT NULL, PRIMARY KEY (`id`), UNIQUE INDEX `user_id` (`user_id`), CONSTRAINT `passwords_users_password` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`) ON UPDATE NO ACTION ON DELETE CASCADE) CHARSET utf8mb4 COLLATE utf8mb4_bin;
-- Create "team_configs" table
CREATE TABLE `team_configs` (`id` varchar(32) NOT NULL, `created_at` datetime(6) NOT NULL, `updated_at` datetime(6) NOT NULL, `kind` enum('model','preset','plugin') NOT NULL, `name` varchar(100) NOT NULL, `data` json NOT NULL, `version` bigint NOT NULL DEFAULT 1, `team_id` varchar(32) NOT NULL, PRIMARY KEY (`id`), UNIQUE INDEX `teamconfig_team_id_kind_name` (`team_id`, `kind`, `name`), CONSTRAINT `team_configs_teams_configs` FOREIGN KEY (`team_id`) REFERENCES `teams` (`id`) ON UPDATE NO ACTION ON DELETE CASCADE) CHARSET utf8mb4 COLLATE utf8mb4_bin;
-- Create "team_providers" table
CREATE TABLE `team_providers` (`id` varchar(32) NOT NULL, `created_at` datetime(6) NOT NULL, `updated_at` datetime(6) NOT NULL, `name` varchar(100) NOT NULL, `base_url` varchar(500) NOT NULL, `key_cipher` longtext NOT NULL, `team_id` varchar(32) NOT NULL, PRIMARY KEY (`id`), UNIQUE INDEX `teamprovider_team_id_name` (`team_id`, `name`), CONSTRAINT `team_providers_teams_providers` FOREIGN KEY (`team_id`) REFERENCES `teams` (`id`) ON UPDATE NO ACTION ON DELETE CASCADE) CHARSET utf8mb4 COLLATE utf8mb4_bin;
